// Load session from Redis
const tenantId = $input.first().json.body.tenant_id;
const customerId = $input.first().json.body.customer_id;
const sessionKey = `session:${tenantId}:${customerId}`;

// Fallback: create new session context if not found
return [{
  json: {
    session_key: sessionKey,
    tenant_id: tenantId,
    customer_id: customerId,
    context: $input.first().json.body.context || {},
    history: $input.first().json.body.history || [],
    config: $input.first().json.data
  }
}];

// Build dynamic prompt based on tenant config + RAG results
const webhook = $('Universal Webhook').first().json;
const session = $('Load Session').first().json;
const ragResults = $input.first().json;
const config = session.config;

// Build context from RAG
let ragContext = '';
if (ragResults.data && ragResults.data.length > 0) {
  ragContext = '\n\n=== INFORMASI BISNIS ===\n';
  for (const doc of ragResults.data) {
    ragContext += `- [${doc.source_type}] ${doc.content}\n`;
  }
}

// Build conversation history
let historyText = '';
if (session.history && session.history.length > 0) {
  const maxMessages = config.max_context_messages || 10;
  const recentHistory = session.history.slice(-maxMessages);
  historyText = '\n\n=== RIWAYAT PERCAKAPAN ===\n';
  for (const msg of recentHistory) {
    historyText += `${msg.role}: ${msg.content}\n`;
  }
}

// System prompt
const systemPrompt = config.system_prompt || 
  `Kamu adalah asisten AI untuk bisnis UMKM. Jawab dengan ${config.tone || 'friendly'} dalam bahasa ${config.language === 'id' ? 'Indonesia' : 'English'}.`;

const fullPrompt = systemPrompt + ragContext + historyText;

return [{
  json: {
    system_prompt: fullPrompt,
    user_message: webhook.body.message,
    tenant_id: session.tenant_id,
    customer_id: session.customer_id,
    channel: webhook.body.channel || 'whatsapp',
    llm_provider: config.llm_provider || 'minimax',
    llm_model: config.llm_model || 'MiniMax-M2.7',
    temperature: config.temperature || 0.7,
    max_tokens: config.max_tokens || 1024,
    config: config
  }
}];

