// Check if escalation is needed
const config = $('Prompt Builder').first().json.config;
const userMessage = $('Prompt Builder').first().json.user_message.toLowerCase();
const aiResponse = $('LLM Call').first().json;

let shouldEscalate = false;
let reason = '';

// 1. Keyword-based escalation
const keywords = config.escalation_keywords || ['bicara cs', 'hubungi admin', 'operator', 'manusia', 'human'];
for (const kw of keywords) {
  if (userMessage.includes(kw.toLowerCase())) {
    shouldEscalate = true;
    reason = 'keyword';
    break;
  }
}

// 2. Low confidence check (jika AI gateway return confidence)
if (!shouldEscalate && aiResponse.confidence !== undefined) {
  const threshold = config.escalation_confidence_threshold || 0.3;
  if (aiResponse.confidence < threshold) {
    shouldEscalate = true;
    reason = 'low_confidence';
  }
}

return [{
  json: {
    should_escalate: shouldEscalate,
    reason: reason,
    response: aiResponse.choices?.[0]?.message?.content || config.fallback_message,
    tenant_id: $('Prompt Builder').first().json.tenant_id,
    customer_id: $('Prompt Builder').first().json.customer_id,
    channel: $('Prompt Builder').first().json.channel
  }
}];

